package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializationConfig;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdBeanPropertyDefinition;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_filterBeanProps_TriageGen0Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private BeanDeserializerBuilder builder;
    private DeserializationConfig config;

    // Subclass to expose protected method for testing
    private static class TestableBeanDeserializerFactory extends BeanDeserializerFactory {
        public TestableBeanDeserializerFactory() {
            super(null);
        }

        @Override
        protected boolean isIgnorableType(DeserializationConfig config, BeanDescription beanDesc, Class<?> type, Map<Class<?>, Boolean> ignoredTypes) {
            // Mocking the behavior of isIgnorableType via the test logic
            // Since we can't easily mock protected methods of the same class in a simple way,
            // we use a spy or just rely on the fact that we can override it in this test subclass.
            return false; 
        }

        // We redefine the method to allow controlled testing of isIgnorableType logic
        // However, to strictly test the original method's interaction, we will use a Spy on the factory.
    }

    @Before
    public void setUp() {
        // We use Mockito to spy on a real instance to allow overriding isIgnorableType
        factory = spy(new TestableBeanDeserializerFactory());
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        builder = mock(BeanDeserializerBuilder.class);
        config = mock(DeserializationConfig.class);

        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testFilterBeanProps_AllPassed() throws JsonMappingException {
        List<BeanPropertyDefinition> props = new ArrayList<>();
        props.add(mockProperty("prop1", false, null));
        props.add(mockProperty("prop2", false, null));

        Set<String> ignored = new HashSet<>();

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, props, ignored);

        assertEquals(2, result.size());
        assertTrue(result.containsAll(props));
    }

    @Test
    public void testFilterBeanProps_ExplicitlyIgnored() throws JsonMappingException {
        List<BeanPropertyDefinition> props = new ArrayList<>();
        props.add(mockProperty("ignoreMe", false, null));
        props.add(mockProperty("keepMe", false, null));

        Set<String> ignored = new HashSet<>(Collections.singletonList("ignoreMe"));

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, props, ignored);

        assertEquals(1, result.size());
        assertEquals("keepMe", result.get(0).getName());
    }

    @Test
    public void testFilterBeanProps_ConstructorParameterNeverSkipped() throws JsonMappingException {
        // Even if it's a "type" that might be ignorable, if hasConstructorParameter is true, it stays
        BeanPropertyDefinition constructorProp = mockProperty("constProp", true, String.class);
        List<BeanPropertyDefinition> props = Collections.singletonList(constructorProp);

        doReturn(true).when(factory).isIgnorableType(eq(config), eq(beanDesc), any(), any());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, props, new HashSet<>());

        assertEquals(1, result.size());
        assertEquals("constProp", result.get(0).getName());
    }

    @Test
    public void testFilterBeanProps_IgnorableSetterType() throws JsonMappingException {
        // Mock property with a setter
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("setterProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanDeserializerBuilder.Setter setter = mock(BeanDeserializerBuilder.Setter.class);
        when(prop.getSetter()).thenReturn(setter);
        when(setter.getRawParameterType(0)).thenReturn(String.class);

        doReturn(true).when(factory).isIgnorableType(eq(config), eq(beanDesc), eq(String.class), any());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, Collections.singletonList(prop), new HashSet<>());

        assertTrue(result.isEmpty());
        verify(builder).addIgnorable("setterProp");
    }

    @Test
    public void testFilterBeanProps_IgnorableFieldType() throws JsonMappingException {
        // Mock property with a field
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("fieldProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(false);
        when(prop.hasField()).thenReturn(true);

        BeanDeserializerBuilder.Field field = mock(BeanDeserializerBuilder.Field.class);
        when(prop.getField()).thenReturn(field);
        when(field.getRawType()).thenReturn(Integer.class);

        doReturn(true).when(factory).isIgnorableType(eq(config), eq(beanDesc), eq(Integer.class), any());

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, Collections.singletonList(prop), new HashSet<>());

        assertTrue(result.isEmpty());
        verify(builder).addIgnorable("fieldProp");
    }

    @Test
    public void testFilterBeanProps_NullRawType() throws JsonMappingException {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn("nullTypeProp");
        when(prop.hasConstructorParameter()).thenReturn(false);
        when(prop.hasSetter()).thenReturn(true);

        BeanDeserializerBuilder.Setter setter = mock(BeanDeserializerBuilder.Setter.class);
        when(prop.getSetter()).thenReturn(setter);
        when(setter.getRawParameterType(0)).thenReturn(null);

        List<BeanPropertyDefinition> result = invokeFilterBeanProps(ctxt, beanDesc, builder, Collections.singletonList(prop), new HashSet<>());

        assertEquals(1, result.size());
    }

    @SuppressWarnings("unchecked")
    private List<BeanPropertyDefinition> invokeFilterBeanProps(DeserializationContext ctxt,
                                                              BeanDescription beanDesc,
                                                              BeanDeserializerBuilder builder,
                                                              List<BeanPropertyDefinition> propDefsIn,
                                                              Set<String> ignored) throws JsonMappingException {
        try {
            java.lang.reflect.Method method = BeanDeserializerFactory.class.getDeclaredMethod(
                    "filterBeanProps", DeserializationContext.class, BeanDescription.class, 
                    BeanDeserializerBuilder.class, List.class, Set.class);
            method.setAccessible(true);
            return (List<BeanPropertyDefinition>) method.invoke(factory, ctxt, beanDesc, builder, propDefsIn, ignored);
        } catch (Exception e) {
            if (e.getCause() instanceof JsonMappingException) {
                throw (JsonMappingException) e.getCause();
            }
            throw new RuntimeException(e);
        }
    }

    private BeanPropertyDefinition mockProperty(String name, boolean isConstructorParam, Class<?> type) {
        BeanPropertyDefinition prop = mock(BeanPropertyDefinition.class);
        when(prop.getName()).thenReturn(name);
        when(prop.hasConstructorParameter()).thenReturn(isConstructorParam);
        if (type != null) {
            // If it's a field type, we need to handle the field mock
            // But for simplicity in this test helper, we assume it's a field-based property if not constructor
            BeanDeserializerBuilder.Field field = mock(BeanDeserializerBuilder.Field.class);
            when(prop.hasField()).thenReturn(true);
            when(prop.getField()).thenReturn(field);
            when(field.getRawType()).thenReturn(type);
        }
        return prop;
    }
}
